package app.kinnect.live;
import android.app.*;
import android.content.Intent;
import android.net.Uri;
import org.json.*;
import java.net.*;
/** Checks published APK releases and opens Android's normal download/install flow. */
public final class ApkUpdates {
 public static void check(Activity activity){ProgressDialog progress=ProgressDialog.show(activity,"Cập nhật Kinnect","Đang kiểm tra phiên bản…",true,false);new Thread(()->{String version=null,url=null,error=null;try{String current=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0).versionName;HttpURLConnection c=(HttpURLConnection)new URL("https://api.github.com/repos/vuanh97nd/Kinnect/releases?per_page=30").openConnection();c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("User-Agent","Kinnect-Android/"+current);JSONArray releases;try{if(c.getResponseCode()!=200)throw new Exception();releases=new JSONArray(new String(NativeApi.read(c.getInputStream(),2000000),"UTF-8"));}finally{c.disconnect();}for(int i=0;i<releases.length();i++){JSONObject r=releases.getJSONObject(i);if(r.optBoolean("draft"))continue;String tag=r.optString("tag_name");try{if(ReleaseVersion.compare(tag,current)<=0||(version!=null&&ReleaseVersion.compare(tag,version)<=0))continue;}catch(IllegalArgumentException invalid){continue;}JSONArray assets=r.optJSONArray("assets");for(int j=0;assets!=null&&j<assets.length();j++){JSONObject asset=assets.getJSONObject(j);String link=asset.optString("browser_download_url");if(asset.optString("name").endsWith(".apk")&&asset.optLong("size")>0&&link.startsWith("https://github.com/vuanh97nd/Kinnect/releases/download/")){version=tag;url=link;break;}}}}catch(Exception e){error="Chưa kiểm tra được cập nhật. Vui lòng thử lại khi có mạng.";}final String v=version,u=url,e=error;activity.runOnUiThread(()->{if(activity.isFinishing()||activity.isDestroyed())return;progress.dismiss();if(e!=null){new Sheet(activity).setMessage(e).setPositiveButton("Đóng",null).show();return;}if(u==null){new Sheet(activity).setTitle("Kinnect đã mới nhất").setMessage("Chưa có APK mới hơn phiên bản đang cài.").setPositiveButton("Xong",null).show();return;}new Sheet(activity).setTitle("Có bản Kinnect "+v).setMessage("Tải APK từ GitHub. Sau khi tải, mở tệp và xác nhận cập nhật trong Android.").setPositiveButton("Tải cập nhật",(d,w)->{try{activity.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));}catch(Exception missing){new Sheet(activity).setMessage("Không tìm thấy ứng dụng mở liên kết tải APK.").setPositiveButton("Đóng",null).show();}}).setNegativeButton("Để sau",null).show();});},"kinnect-updates").start();}
}
